using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.Net.Mail;
namespace Society.Api;

public static class SocietyEndpoints
{
    public static void Map(RouteGroupBuilder api)
    {
        api.MapPost("/societies/applications", async (ApplicationRequest r, AppDb db, Access a) => { if (string.IsNullOrWhiteSpace(r.Name) || r.Name.Length > 160 || string.IsNullOrWhiteSpace(r.Address) || string.IsNullOrWhiteSpace(r.Country) || !MailAddress.TryCreate(r.OfficialEmail, out _) || string.IsNullOrWhiteSpace(r.ContactNumber) || string.IsNullOrWhiteSpace(r.ApplicantMobile)) throw new DomainException("Complete the society name, address, country, contact details and official email"); var app = new Application { ApplicantId = a.UserId, Name = r.Name.Trim(), Fingerprint = r.Name.Trim().ToUpperInvariant() + "|" + r.Country.Trim().ToUpperInvariant() + "|" + r.City.Trim().ToUpperInvariant(), Details = JsonSerializer.Serialize(r) }; db.Applications.Add(app); a.Audit(Guid.Empty, "application.submitted", app.Id); await db.SaveChangesAsync(); return Results.Ok(new { app.Id }); }).RequireAuthorization();
        api.MapGet("/societies/applications", async (AppDb db, Access a, int? page) => { var platform = await a.Platform(); return await db.Applications.Where(x => platform || x.ApplicantId == a.UserId).OrderByDescending(x => x.CreatedAt).Skip(Math.Clamp((page ?? 1) - 1, 0, 1000000) * 100).Take(100).Select(x => new { x.Id, x.Name, x.Status, x.ReviewNote, x.TenantId, x.CreatedAt, x.Details }).ToListAsync(); }).RequireAuthorization();
        api.MapPost("/societies/applications/{id:guid}/review", async (Guid id, ReviewRequest r, AppDb db, Access a) =>
        {
            await a.RequirePlatform(); await using var tx = await db.Database.BeginTransactionAsync(); var application = await db.Applications.FromSqlInterpolated($"SELECT * FROM \"Applications\" WHERE \"Id\"={id} FOR UPDATE").SingleOrDefaultAsync(); if (application == null) return Results.NotFound(); if (application.Status != "Pending") throw new DomainException("Application already reviewed"); application.ReviewNote = r.Note;
            if (r.Approve) { var tenant = new Tenant { Name = application.Name, Profile = application.Details }; db.Tenants.Add(tenant); db.Links.Add(new Link { TenantId = tenant.Id, UserId = application.ApplicantId }); var role = new GovernanceRole { TenantId = tenant.Id, Name = "Society Administrator", Permissions = Access.Permissions }; db.GovernanceRoles.Add(role); db.GovernanceRoles.AddRange(RoleTemplates.For(tenant.Id)); db.Assignments.Add(new Assignment { TenantId = tenant.Id, RoleId = role.Id, UserId = application.ApplicantId }); db.Onboardings.Add(new Onboarding { TenantId = tenant.Id }); application.TenantId = tenant.Id; application.Status = "Approved"; var region = new Level { TenantId = tenant.Id, Name = "Region", Kind = "Region", AllowRoot = true }; var chapter = new Level { TenantId = tenant.Id, Name = "Chapter", Kind = "Chapter", AllowedParents = [region.Id] }; db.Levels.AddRange(region, chapter); await MembershipSeed.Ensure(db, tenant.Id); a.Audit(tenant.Id, "society.approved", tenant.Id); } else { application.Status = "Rejected"; a.Audit(Guid.Empty, "application.rejected", application.Id, new { r.Note }); }
            await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.Ok(new { application.TenantId, application.Status });
        }).RequireAuthorization();
        api.MapGet("/workspaces", async (AppDb db, Access a) =>
        {
            var now = DateTimeOffset.UtcNow;
            var rows = await (from link in db.Links join tenant in db.Tenants on link.TenantId equals tenant.Id where link.UserId == a.UserId select new { tenant.Id, tenant.Name, tenant.Status, tenant.Profile, scopes = (from ass in db.Assignments join role in db.GovernanceRoles on ass.RoleId equals role.Id where ass.TenantId == tenant.Id && ass.UserId == a.UserId && ass.RevokedAt == null && ass.StartsAt <= now && (ass.EndsAt == null || ass.EndsAt > now) && (ass.MembershipId == null || db.Memberships.Any(m => m.Id == ass.MembershipId && m.TenantId == tenant.Id && m.Status == "Active" && m.EffectiveFrom <= now && (m.EndsAt == null || m.EndsAt > now))) select new { ass.UnitId, role.Name, role.Permissions, unitName = db.Units.Where(u => u.Id == ass.UnitId && u.TenantId == tenant.Id).Select(u => u.Name).FirstOrDefault() }).ToArray() }).ToListAsync();
            return rows.Select(w => new { w.Id, w.Name, w.Status, profile = PublicBranding(w.Profile), w.scopes });
        }).RequireAuthorization();
        api.MapGet("/platform/societies", async (AppDb db, Access a, int? page) => { await a.RequirePlatform(); return await db.Tenants.OrderBy(x => x.Name).Skip(Math.Max(0, (page ?? 1) - 1) * 30).Take(30).Select(x => new { x.Id, x.Name, x.Status, x.CreatedAt }).ToListAsync(); }).RequireAuthorization();
        api.MapPost("/platform/societies/{id:guid}/status", async (Guid id, ReviewRequest r, AppDb db, Access a) => { await a.RequirePlatform(); var tenant = await db.Tenants.FindAsync(id); if (tenant == null) return Results.NotFound(); tenant.Status = r.Approve ? "Active" : "Suspended"; a.Audit(Guid.Empty, "society.lifecycle", id, new { tenant.Status, r.Note }); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization();
        InvitationEndpoints.Map(api);
        var t = api.MapGroup("/societies/{tenant:guid}").RequireAuthorization();
        t.MapGet("/dashboard", async (Guid tenant, Guid? workspace, AppDb db, Access a) => { await a.Member(tenant); var visible = a.InWorkspace(a.Visible(tenant), tenant, workspace); return new { society = await db.Tenants.Where(x => x.Id == tenant).Select(x => new { x.Id, x.Name, x.Status }).SingleAsync(), units = await visible.CountAsync(), regions = await visible.CountAsync(x => db.Levels.Any(l => l.Id == x.LevelId && l.Kind == "Region")), chapters = await visible.CountAsync(x => db.Levels.Any(l => l.Id == x.LevelId && l.Kind == "Chapter")), active = await visible.CountAsync(x => x.Status == "Active") }; });
        t.MapGet("/settings", async (Guid tenant, AppDb db, Access a) => { await a.Require(tenant, "settings.manage"); return await db.Tenants.Where(x => x.Id == tenant).Select(x => new { x.Name, x.Profile, x.Status }).SingleAsync(); });
        t.MapPut("/settings", async (Guid tenant, JsonElement r, AppDb db, Access a) => { await a.Require(tenant, "settings.manage"); if (r.GetRawText().Length > 32000) throw new DomainException("Settings too large"); SettingsPolicy.Validate(r, tenant); var s = await db.Tenants.FindAsync(tenant); s!.Profile = r.GetRawText(); a.Audit(tenant, "settings.updated", tenant); await db.SaveChangesAsync(); return Results.NoContent(); });
        t.MapGet("/onboarding", async (Guid tenant, AppDb db, Access a) => { await a.Require(tenant, "settings.manage"); return await db.Onboardings.Where(x => x.TenantId == tenant).Select(x => new { x.Step, x.Data, x.Complete }).SingleAsync(); });
        t.MapPut("/onboarding", async (Guid tenant, OnboardingRequest r, AppDb db, Access a) => { await a.Require(tenant, "settings.manage"); if (r.Step < 0 || r.Step > 7 || r.Data.Length > 32000) throw new DomainException("Invalid wizard progress"); using var wizardDocument = JsonDocument.Parse(r.Data); SettingsPolicy.Validate(wizardDocument.RootElement, tenant); var o = (await db.Onboardings.FindAsync(tenant))!; o.Step = r.Step; o.Data = r.Data; var society = (await db.Tenants.FindAsync(tenant))!; var profile = System.Text.Json.Nodes.JsonNode.Parse(society.Profile)!.AsObject(); var wizard = System.Text.Json.Nodes.JsonNode.Parse(r.Data)!.AsObject(); foreach (var pair in wizard) profile[pair.Key] = pair.Value?.DeepClone(); society.Profile = profile.ToJsonString(); if (wizard["displayName"]?.GetValue<string>() is { } display && !string.IsNullOrWhiteSpace(display)) { if (display.Length > 160) throw new DomainException("Society name must be at most 160 characters"); society.Name = display.Trim(); } if (r.Activate) { if (!await db.Levels.AnyAsync(x => x.TenantId == tenant)) throw new DomainException("Configure at least one hierarchy level"); o.Complete = true; (await db.Tenants.FindAsync(tenant))!.Status = "Active"; } a.Audit(tenant, r.Activate ? "society.activated" : "onboarding.saved", tenant); await db.SaveChangesAsync(); return Results.NoContent(); });
        t.MapGet("/audit-logs", async (Guid tenant, int? page, AppDb db, Access a) => { await a.Require(tenant, "audit.read"); return await db.Audits.Where(x => x.TenantId == tenant).OrderByDescending(x => x.At).Skip(Math.Max(0, (page ?? 1) - 1) * 30).Take(30).Select(x => new { x.Id, x.Action, x.ResourceId, x.At, x.ActorId, x.Details }).ToListAsync(); });
    }
    static string PublicBranding(string profile) { using var document = JsonDocument.Parse(profile); var root = document.RootElement; return JsonSerializer.Serialize(new { brandColor = root.TryGetProperty("brandColor", out var color) ? color.GetString() : null, logoUrl = root.TryGetProperty("logoUrl", out var logo) ? logo.GetString() : null }); }

}
